retained_functions.compact:
def compact(d):
    out = {}
    for k,v in d.items():
        if k=='changed_cell_count': out[k]=v
        else:
            out[k]=[{kk:vv for kk,vv in e.items() if kk in ('at','at_before','at_after','pixels','color','before_color','after_color','rotated_by')} for e in v]
    return out

retained_functions.heads:
def heads(fr):
    out=[]
    for n in fr.segmentation['nodes']:
        if n['color'] in ('g','p','W') and 20 <= min(p[0] for p in n['boundary']) <= 45:
            b=n['boundary']; r0=min(p[0] for p in b); r1=max(p[0] for p in b); c0=min(p[1] for p in b); c1=max(p[1] for p in b)
            out.append((n['color'],n['pixels'],(r0,c0,r1,c1),n['rotation'],n['rotational_symmetry']))
    return out

retained_functions.canvas:
def canvas(fr):
    lines = fr.ascii.split('\n')
    return [lines[r][27:37] for r in range(34,44)]

