def mold(fr):
    for n in fr.segmentation['nodes']:
        if n['color']=='g':
            b=n['boundary']; return (n['pixels'],(min(p[0] for p in b),min(p[1] for p in b),max(p[0] for p in b),max(p[1] for p in b)),n['rotation'])

